#include <iostream>
#include <map>
#include <string>

struct Total {
    long long v = 0;
    Total& operator+=(long long x) {
        v += x;
        return *this;
    }
};

int main() {
    int n;
    std::cin >> n;
    std::map<std::string, Total> m;
    for (int i = 0; i < n; i++) {
        std::string s;
        long long a;
        std::cin >> s >> a;
        m[s] += a;
    }
    for (const auto& p : m) {
        std::cout << p.first << " " << p.second.v << "\n";
    }
    return 0;
}
